from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit, unquote

root = Path('docs/.vitepress/dist')
class Page(HTMLParser):
    def __init__(self, path):
        super().__init__()
        self.ids = set()
        self.links = []
        self.feed(path.read_text())
    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if 'id' in attrs:
            self.ids.add(attrs['id'])
        if tag == 'a' and 'href' in attrs:
            self.links.append(attrs['href'])

cache = {}
def page(path):
    if path not in cache:
        cache[path] = Page(path)
    return cache[path]

errors = []
count = 0
paths = ['dev-tools/backends/packslip.html', 'dev-tools/packslip-resources.html']
for name in paths:
    for link in page(root / name).links:
        url = urlsplit(urljoin('https://mise.jdx.dev/' + name, link))
        if url.netloc != 'mise.jdx.dev' or url.scheme not in ('http', 'https'):
            continue
        target = root / unquote(url.path.lstrip('/'))
        if target.is_dir():
            target /= 'index.html'
        elif not target.suffix:
            target = target.with_suffix('.html')
        count += 1
        if not target.exists():
            errors.append(f'{name}: missing {link}')
        elif url.fragment and target.suffix == '.html' and unquote(url.fragment) not in page(target).ids:
            errors.append(f'{name}: missing anchor {link}')
print(f'Checked {count} local links and anchors across {len(paths)} Packslip pages')
if errors:
    raise SystemExit('\n'.join(errors))
